package inventory

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"strconv"

	"github.com/santhosh-tekuri/jsonschema/v6"
	"gopkg.in/yaml.v3"

	"heartbeat/apps/api/internal/store"
	"heartbeat/internal/config"
	configschema "heartbeat/packages/config-schema"
)

// RenderHeader starts every rendered file: what made it, and that a hand
// edit is overwritten.
const RenderHeader = `# Generated by the Heartbeat API from approved probe assignments (ADR 0014).
# Do not edit: the API overwrites this file. Pass it to helm after the
# environment's own values; the chart appends managedCollectors to
# integrations.collectors.
`

// RenderError is a render the collector would refuse. It should not
// happen: every change is checked before it is stored, and an approval
// checks the render that holds it.
type RenderError struct{ Reason string }

func (e *RenderError) Error() string {
	return "the rendered managedCollectors are invalid: " + e.Reason
}

// managedValues is the rendered values file.
type managedValues struct {
	ManagedCollectors []managedCollector `yaml:"managedCollectors"`
}

// managedCollector is a collector as integrations.collectors holds one,
// with the keys a render sets, in the order it writes them. Its JSON form
// is what the integrations schema checks.
type managedCollector struct {
	ID      string          `yaml:"id" json:"id"`
	Kind    string          `yaml:"kind" json:"kind"`
	Enabled bool            `yaml:"enabled" json:"enabled"`
	Config  collectorConfig `yaml:"config" json:"config"`
}

type collectorConfig struct {
	Environment    string          `yaml:"environment" json:"environment"`
	ScrapeInterval string          `yaml:"scrape_interval" json:"scrape_interval"`
	Targets        []managedTarget `yaml:"targets" json:"targets"`
}

type managedTarget struct {
	Name          string         `yaml:"name" json:"name"`
	Environment   string         `yaml:"environment" json:"environment"`
	Host          string         `yaml:"host" json:"host"`
	Port          int            `yaml:"port" json:"port"`
	DatabaseName  string         `yaml:"database_name,omitempty" json:"database_name,omitempty"`
	CredentialRef string         `yaml:"credential_ref" json:"credential_ref"`
	Probes        []managedProbe `yaml:"probes" json:"probes"`
}

type managedProbe struct {
	Name          string `yaml:"name" json:"name"`
	QueryTemplate string `yaml:"query_template,omitempty" json:"query_template,omitempty"`
	TimeoutMS     int    `yaml:"timeout_ms,omitempty" json:"timeout_ms,omitempty"`
	MaxRows       int    `yaml:"max_rows,omitempty" json:"max_rows,omitempty"`
}

// collectorSchema is integrations.schema.json's collector.
var collectorSchema = func() *jsonschema.Schema {
	schema, err := configschema.CollectorSchema()
	if err != nil {
		panic(err) // embedded, and tested
	}
	return schema
}()

// RenderProbeAssignments renders every approved, enabled assignment of an
// active target and an enabled definition into the values file that holds
// managedCollectors (ADR 0014 §2): one sqlserver collector per target, with
// the ID api-<target id>-<interval>s. A built-in definition is listed by
// name; a custom one by the name of the probe it overrides, with its query
// in full, for review. The output is deterministic, sorted and without
// timestamps, so the same approvals render the same bytes; it is checked
// with the integrations schema and the collector's own loader before it is
// returned.
func (s *Service) RenderProbeAssignments(ctx context.Context) ([]byte, error) {
	return render(ctx, store.New(s.db))
}

func render(ctx context.Context, q *store.Queries) ([]byte, error) {
	rows, err := q.ListRenderedProbeAssignments(ctx)
	if err != nil {
		return nil, fmt.Errorf("list the approved probe assignments: %w", err)
	}
	values := managedValues{ManagedCollectors: []managedCollector{}}
	byTarget := map[[16]byte]int{}
	for _, row := range rows {
		i, seen := byTarget[row.TargetID.Bytes]
		if !seen {
			i = len(values.ManagedCollectors)
			byTarget[row.TargetID.Bytes] = i
			values.ManagedCollectors = append(values.ManagedCollectors, managedCollector{
				ID: CollectorID(goUUID(row.TargetID), int(row.IntervalSeconds)), Kind: config.KindSQLServer, Enabled: true,
				Config: collectorConfig{
					Environment:    row.EnvironmentSlug,
					ScrapeInterval: strconv.Itoa(int(row.IntervalSeconds)) + "s",
					Targets: []managedTarget{{
						Name: row.TargetName, Environment: row.EnvironmentSlug, Host: row.Host, Port: int(row.Port),
						DatabaseName: row.DatabaseName.String, CredentialRef: row.CredentialRef, Probes: []managedProbe{},
					}},
				},
			})
		}
		c := &values.ManagedCollectors[i]
		if want := CollectorID(goUUID(row.TargetID), int(row.IntervalSeconds)); c.ID != want {
			return nil, &RenderError{Reason: fmt.Sprintf("database target %s has approved assignments at two intervals, %s and %ds; a target runs at one", goUUID(row.TargetID), c.Config.ScrapeInterval, row.IntervalSeconds)}
		}
		c.Config.Targets[0].Probes = append(c.Config.Targets[0].Probes, renderedProbe(row))
	}
	// Rows come sorted by target, then probe; collectors are sorted by ID,
	// which starts with the target's.
	var out bytes.Buffer
	out.WriteString(RenderHeader)
	enc := yaml.NewEncoder(&out)
	enc.SetIndent(2)
	if err := enc.Encode(values); err != nil {
		return nil, fmt.Errorf("encode the managedCollectors: %w", err)
	}
	if err := enc.Close(); err != nil {
		return nil, fmt.Errorf("encode the managedCollectors: %w", err)
	}
	if err := checkRender(values); err != nil {
		return nil, err
	}
	return out.Bytes(), nil
}

// renderedProbe is the probe an assignment runs, as the collector reads it:
// the timeout its own, or else its definition's, or left to the collector.
func renderedProbe(row store.ListRenderedProbeAssignmentsRow) managedProbe {
	p := managedProbe{Name: row.ProbeName, MaxRows: int(row.MaxRows.Int32)}
	if !row.Builtin {
		p.QueryTemplate = row.QueryTemplate.String
	}
	switch {
	case row.TimeoutMs.Valid:
		p.TimeoutMS = int(row.TimeoutMs.Int32)
	case row.DefinitionTimeoutMs.Valid:
		p.TimeoutMS = int(row.DefinitionTimeoutMs.Int32)
	}
	return p
}

// checkRender checks every rendered collector against the integrations
// schema, and all of them with the collector's loader, as an integrations
// file of their own.
func checkRender(values managedValues) error {
	for _, c := range values.ManagedCollectors {
		raw, err := json.Marshal(c)
		if err != nil {
			return fmt.Errorf("encode collector %s: %w", c.ID, err)
		}
		doc, err := jsonschema.UnmarshalJSON(bytes.NewReader(raw))
		if err != nil {
			return fmt.Errorf("decode collector %s: %w", c.ID, err)
		}
		if err := collectorSchema.Validate(doc); err != nil {
			return &RenderError{Reason: fmt.Sprintf("collector %s: %v", c.ID, err)}
		}
	}
	file, err := yaml.Marshal(map[string]any{"collectors": values.ManagedCollectors})
	if err != nil {
		return fmt.Errorf("encode the collectors: %w", err)
	}
	if _, err := config.ParseRuntimeConfig(file); err != nil {
		return &RenderError{Reason: err.Error()}
	}
	return nil
}
